class Lru<K, V> {
  final int capacity;
  final _map = <K, V>{};
  Lru(this.capacity);

  V? get(K key) {
    final v = _map.remove(key);
    if (v == null) return null;
    _map[key] = v;
    return v;
  }

  void put(K key, V value) {
    _map.remove(key);
    _map[key] = value;
    if (_map.length > capacity) _map.remove(_map.keys.first);
  }

  List<K> get order => _map.keys.toList();
}

