var calls = 0;
final cache = Lru<int, int>(2);

int slowSquare(int x) {
  final hit = cache.get(x);
  if (hit != null) return hit;
  calls++;
  final r = x * x;
  cache.put(x, r);
  return r;
}

void main() {
  for (final x in [2, 3, 2, 4, 2, 3]) {
    slowSquare(x);
  }
  print(calls);
}
